//! Whole immutable old AutoTracked producer over the ACTUAL old gen CLI domain.
pub use dq_analyze::{sem,tree,scopes,pat,util,reactive_facts,raw_marker_policy,lint,parity,incr,gens,pat_match};
#[path="support/deps_original/reaction_producer.rs"]pub mod original_reaction;mod lints{pub use crate::original_reaction as derived_reads;}
#[path="support/deps_original/projected.rs"]mod deps;#[path="support/auto_generator_original/projected.rs"]mod auto_tracked;
use std::{collections::BTreeSet,path::PathBuf};
fn legacy_file_of(sem:&sem::Sem,location:dreammaker::Location)->Option<&str>{if location.is_builtins(){None}else{let relative=sem.rel(location);(!relative.is_empty()).then_some(relative)}}
fn legacy_canonical_read_key(kind:&sem::reads::ReadKind,name:&str,keys:&BTreeSet<String>,defines:&BTreeSet<String>)->String{if *kind==sem::reads::ReadKind::Accessor&&keys.contains(name){format!("capkey:[{name}]")}else if *kind==sem::reads::ReadKind::Accessor&&defines.contains(name){format!("[{name}]")}else{name.to_owned()}}
fn main()->Result<(),Box<dyn std::error::Error>>{
 let original=include_str!("support/auto_generator_original/producer.rs");let expected=original.replace("sem.file_of(p.get().location)","crate::legacy_file_of(&sem,p.get().location)").replace("sem.file_of(rel)","crate::legacy_file_of(&sem,rel)").replace("sem.file_of(loc)","crate::legacy_file_of(&sem,loc)").replace("sem.file_of(v.location)","crate::legacy_file_of(&sem,v.location)");assert_eq!(include_str!("support/auto_generator_original/projected.rs"),expected,"only private file lookup transport differs from immutable whole old producer");
 let root=PathBuf::from(std::env::args().nth(1).ok_or("fixture root required")?);let root=if root.is_absolute(){root}else{std::env::current_dir()?.join(root)};
 let engine=dq_analyze::run::Engine::new(dq_analyze::run::registry(),dq_analyze::run::Options{root:root.clone(),lints:vec!["sem/keys".to_owned()],raw:true,no_cache:true,..Default::default()})?;let owner=sem::sem_for(&engine.tree).ok_or("whole original semantic owner unavailable")?;if !owner.errors.is_empty(){return Err(format!("whole original parse errors: {:?}",owner.errors).into())}
 let inferred=auto_tracked::inferred(&engine.tree);let set=inferred.as_ref().as_ref().ok_or("whole original AutoTracked result unavailable")?;if set.tracked.is_empty(){return Err("whole original fixture must actually generate tracking".into())}
 let mut registry=Vec::new();auto_tracked::register(&mut registry);let generator=registry.iter().find(|value|value.name()=="auto_tracked").ok_or("whole original generator missing")?;let mut out=sem::gen::GenOut::default();generator.generate(&sem::gen::GenCx::new(&engine.tree,&root),&mut out);let mut text=format!("// GENERATED by tools/analyze: \x60analyze gen {}\x60. Do not edit by hand; edit the declarations it reads.\n// Written to code/engine/_generated/{}; not committed: every build regenerates it (\x60analyze gen\x60).\n\n",generator.name(),generator.output());text.push_str(out.text());if !text.ends_with('\n'){text.push('\n')}
 println!("OLD_AUTO_FULL={}",serde_json::to_string(&serde_json::json!({"path":format!("code/engine/_generated/{}",generator.output()),"text":text,"diagnostics":out.diags.iter().map(|value|(&value.rel,value.line,&value.msg)).collect::<Vec<_>>()}))?);println!("OLD_AUTO_DECISIONS={}",serde_json::to_string(&serde_json::json!({"tracked":set.tracked.iter().map(|row|(&row.ty,&row.var,row.list)).collect::<Vec<_>>(),"blocked":set.blocked}))?);Ok(())
}
